'use strict';
// Loads self-hosted Umami analytics if the server configured it (see /config.js, generated by
// nginx from env vars). Umami is cookieless and stores no IP addresses.
(() => {
  const c = window.__ANALYTICS__ || {};
  window.track = (name, data) => { try { if (window.umami) window.umami.track(name, data); } catch { /* ignore */ } };
  if (!c.host || !c.id || !/^https:\/\/[a-z0-9.-]+(:\d+)?$/i.test(c.host)) return;
  const s = document.createElement('script');
  s.defer = true;
  s.src = c.host + '/' + (c.script || 'script.js');
  s.dataset.websiteId = c.id;
  if (c.domains) s.dataset.domains = c.domains;   // only count visits on the real domain(s)
  s.dataset.doNotTrack = 'true';                  // respect the browser's Do Not Track setting
  document.head.appendChild(s);
})();
